#include <iostream>
#include <vector>
#include <cstdlib>
using namespace std;
int main() {
    int cases; cin >> cases;
    while (cases--) {
        int count; cin >> count;
        vector<int> houses(count);
        int sum = 0;
        for (int i = 0; i < count; ++i) {
            cin >> houses[i];
            sum += houses[i];
        }
        int place = sum / count;
        int total = 0;
        for (int i = 0; i < count; ++i) total += abs(houses[i] - place);
        cout << total << endl;
    }
    return 0;
}

